// @name Download to assets
// @background #eef1f4
// @refresh 3600
// Downloads files from the web into the frame's assets folder, where other
// scenes (a gallery, the Files scene, a font) find them. The addresses are the
// public `urls` field, one a line (`https://… -> name.ext` to pick the name),
// and can be typed on the frame too. A download goes a chunk at a time, so a
// big file works on an ESP32: a few chunks a render, and renders follow each
// other until it is done. The folder's files are listed beside the queue, to
// delete with a confirm.
import { parseLine, cleanFolder, joinPath, freeName, sizeText, ofText, timeLeft, step } from './download'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    page: 'bg-[#eef1f4] text-[#1c2533]',
    muted: 'text-[#5d6b7e]',
    card: 'bg-white',
    field: 'bg-white focus:bg-[#f0f7ff] placeholder:text-[#8a96a8]',
    button: 'bg-[#dfe5ec] text-[#1c2533] active:bg-[#cdd6e0]',
    primary: 'bg-[#1d5c96] text-white active:bg-[#174a79]',
    remove: 'bg-[#b42318] text-white active:bg-[#912018]',
    error: 'text-[#b42318]',
    ok: 'text-[#17714a]',
    track: 'bg-[#dfe5ec]',
    fill: 'bg-[#1d5c96]',
    heading: 'text-[#5d6b7e]',
    icon: 'text-[#1d5c96]',
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white border-2 border-black',
    field: 'bg-white border-2 border-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    remove: 'bg-black text-white',
    error: 'text-black font-bold',
    ok: 'text-black',
    track: 'bg-white border-2 border-black',
    fill: 'bg-black',
    heading: 'text-black',
    icon: 'text-black',
  },
}

const CHUNK_SIZES = [16, 64, 256, 1024]
const baseName = (path) => String(path || '').split('/').pop()

function readDownloads(app) {
  let value = app.state.downloads
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value)
    } catch (e) {
      value = null
    }
  }
  if (!value || typeof value !== 'object') value = {}
  return {
    queue: Array.isArray(value.queue) ? value.queue.filter((q) => typeof q === 'string') : [],
    force: Array.isArray(value.force) ? value.force.filter((q) => typeof q === 'string') : [],
    active: value.active && typeof value.active === 'object' && value.active.line ? value.active : null,
    results: value.results && typeof value.results === 'object' ? value.results : {},
  }
}

const flag = (value, fallback) => (value === undefined || value === null || value === '' ? fallback : value === true || value === 'true')

function settingsOf(app) {
  const chunkKb = Number(app.state.chunkKb)
  const maxMb = Number(app.state.maxMb)
  return {
    folder: cleanFolder(app.state.folder ?? 'Downloads'),
    existing: ['skip', 'overwrite', 'rename'].includes(app.state.existing) ? app.state.existing : 'skip',
    chunk: (CHUNK_SIZES.includes(chunkKb) ? chunkKb : 64) * 1024,
    maxBytes: maxMb > 0 ? maxMb * 1048576 : Number.MAX_SAFE_INTEGER,
    auto: flag(app.state.autoDownload, false),
  }
}

// The URLs field as lines, blank ones and #comments left out.
const linesOf = (text) =>
  String(text || '')
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#'))

// The next line of the queue made into a job, or a result when there is
// nothing to download (a line that is not a URL, a file that is there).
// A line asked for again (`force`) replaces its file when skipping is the rule.
function startJob(line, settings, force) {
  const parsed = parseLine(line)
  if (parsed.error) return { job: null, result: { s: 'failed', error: parsed.error, at: Date.now() } }
  let name = parsed.name
  const there = frameos.assetExists(joinPath(settings.folder, name))
  if (there && settings.existing === 'skip' && !force) return { job: null, result: { s: 'skipped', path: joinPath(settings.folder, name), at: Date.now() } }
  if (there && settings.existing === 'rename') name = freeName(settings.folder, name)
  const path = joinPath(settings.folder, name)
  return { job: { line, url: parsed.url, path, offset: 0, retries: 0, chunks: 0, startedAt: Date.now() }, result: null }
}

// Downloads for a while: about a second on a fast screen, so its progress
// shows as it goes, and half a minute on e-paper, where each picture is a
// refresh. Returns the downloads as they are now.
function work(downloads, settings, embedded, budgetMs) {
  let { queue, force, active, results } = downloads
  queue = queue.slice()
  results = { ...results }
  const began = Date.now()
  const limits = { chunk: settings.chunk, maxBytes: settings.maxBytes, embedded }
  // A download a restart cut short goes on from what is on the disk.
  if (active && active.offset > 0) {
    const size = frameos.assetSize(active.path)
    if (size !== active.offset) active = { ...active, offset: size > 0 ? size : 0 }
  }
  while ((active || queue.length) && Date.now() - began < budgetMs) {
    if (!active) {
      const line = queue.shift()
      const started = startJob(line, settings, force.includes(line))
      force = force.filter((l) => l !== line)
      if (started.result) results[line] = started.result
      active = started.job
      continue
    }
    const next = step(active, limits)
    if (next.result) results[active.line] = { ...next.result, ms: Date.now() - active.startedAt }
    active = next.job
    // A failed chunk is tried again on the next render, not at once.
    if (active && active.retries) break
  }
  return { queue, force, active, results }
}

const Icon = ({ d, size, className }) => (
  <svg className={`w-[${size}px] h-[${size}px] ${className || ''}`} viewBox="0 0 24 24">
    <path d={d} fill="currentColor" />
  </svg>
)
const DOWNLOAD = 'M5,20H19V18H5M19,9H15V3H9V9H5L12,16L19,9Z'
const FILE = 'M14,2H6A2,2 0 0,0 4,4V20A2,2 0 0,0 6,22H18A2,2 0 0,0 20,20V8L14,2M18,20H6V4H13V9H18V20Z'
const BIN = 'M9,3V4H4V6H5V19A2,2 0 0,0 7,21H17A2,2 0 0,0 19,19V6H20V4H15V3H9M7,6H17V19H7V6M9,8V17H11V8H9M13,8V17H15V8H13Z'
const CLOSE = 'M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z'

// The folder's own files, by name, with their sizes. A runtime before
// 2026.11.8 lists every file below: those in subfolders are left out.
function filesIn(folder) {
  const prefix = folder ? folder + '/' : ''
  const list = frameos.listAssets(folder, { shallow: true }) || []
  const files = []
  for (const path of list) {
    if (!path.startsWith(prefix) || path.endsWith('/')) continue
    if (path.slice(prefix.length).includes('/')) continue
    files.push({ path, name: path.slice(prefix.length), size: frameos.assetSize(path) })
  }
  files.sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()))
  return files
}

// A round panel: the title in the arc at the top, and the page under it in
// the room the circle leaves, as wide as it is at the bottom of that room.
export function get(app, context) {
  if (context.round !== true) return draw(app, context)
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const R = Math.min(W, H) / 2 - 12
  const top = Math.round(R * 0.5)
  const bottom = Math.round(R * 0.66)
  const boxW = Math.floor(2 * Math.sqrt(R * R - bottom * bottom))
  // The title over the page, as big as the circle is wide at its top edge.
  const headH = Math.round(Math.min(56, R * 0.3))
  const headTop = Math.round(H / 2 - top - 4 - headH)
  const headW = Math.floor(2 * Math.sqrt(R * R - (H / 2 - headTop) ** 2))
  const titlePx = Math.max(14, Math.min(20, Math.floor((headW - 8) / 10.5)))
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const folder = settingsOf(app).folder
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${Math.round((W - headW) / 2)}px] top-[${headTop}px] w-[${headW}px] h-[${headH}px] flex flex-col items-center justify-center`}>
        <div className="flex items-center gap-[6px]">
          <Icon d={DOWNLOAD} size={Math.round(titlePx * 1.2)} className={`shrink-0 ${t.icon}`} />
          <span className={`text-[${titlePx}px] font-bold whitespace-nowrap`}>Download to assets</span>
        </div>
        <span className={`text-[${Math.min(14, titlePx - 3)}px] ${t.muted} truncate`}>{`Into ${folder ? folder + '/' : 'the assets folder'}`}</span>
      </div>
      <div className={`absolute left-[${Math.round((W - boxW) / 2)}px] top-[${Math.round(H / 2 - top)}px] w-[${boxW}px] h-[${top + bottom}px]`}>
        {draw(app, { ...context, imageWidth: boxW, imageHeight: top + bottom, roundBox: true })}
      </div>
    </div>
  )
}

function draw(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  // Sizes are made for 800x480 (and 480x800) and grow or shrink with the canvas.
  const z = Math.max(0.85, Math.min(2.5, Math.min(W, H) / 480, Math.max(W, H) / 800))
  const px = (n) => Math.round(n * z)
  const t = highContrast(app) ? THEMES.high : THEMES.color
  const fast = app.frame.fast ?? !app.frame.paper
  const embedded = app.frame.embedded === true
  const settings = settingsOf(app)
  const lines = linesOf(app.state.urls)

  let downloads = readDownloads(app)
  // Download new lines by themselves, when the settings say so.
  if (settings.auto) {
    const waiting = lines.filter((l) => !downloads.results[l] && !downloads.queue.includes(l) && !(downloads.active && downloads.active.line === l))
    if (waiting.length) downloads = { ...downloads, queue: downloads.queue.concat(waiting) }
  }
  if (downloads.active || downloads.queue.length) {
    downloads = work(downloads, settings, embedded, fast ? 1200 : 30000)
    // Results for lines no longer in the field go.
    const results = {}
    for (const line of lines) if (downloads.results[line]) results[line] = downloads.results[line]
    downloads = { ...downloads, results }
    frameos.setState('downloads', downloads)
    // Not done: draw again soon and go on.
    if (downloads.active || downloads.queue.length) frameos.setNextSleep(fast ? 0.05 : 0.5)
  }
  const busy = !!(downloads.active || downloads.queue.length)

  const draft = frameos.recall('draft') || ''
  const asking = frameos.recall('asking') || ''
  const save = (next) => frameos.setState('downloads', next)
  const queueLines = (more, again) => {
    const current = readDownloads(app)
    const queue = current.queue.concat(more.filter((l) => !current.queue.includes(l) && !(current.active && current.active.line === l)))
    const force = again ? current.force.concat(more.filter((l) => !current.force.includes(l))) : current.force
    const results = { ...current.results }
    for (const line of more) delete results[line]
    save({ ...current, queue, force, results })
  }
  const addTyped = () => {
    const line = (frameos.recall('draft') || '').trim()
    if (!line) return
    if (!lines.includes(line)) frameos.setState('urls', [...String(app.state.urls || '').split('\n').filter((l) => l.trim()), line].join('\n'))
    frameos.remember('draft', '')
    queueLines([line])
  }
  const stop = () => {
    const current = readDownloads(app)
    if (!current.active) return
    if (current.active.offset > 0) frameos.deleteAsset(current.active.path)
    save({
      ...current,
      active: null,
      results: { ...current.results, [current.active.line]: { s: 'stopped', path: current.active.path, at: Date.now() } },
    })
  }
  const removeLine = (line) => {
    const current = readDownloads(app)
    const queue = current.queue.filter((l) => l !== line)
    const force = current.force.filter((l) => l !== line)
    const results = { ...current.results }
    delete results[line]
    save({ ...current, queue, force, results })
    frameos.setState('urls', String(app.state.urls || '').split('\n').filter((l) => l.trim() !== line).join('\n'))
  }

  const pending = lines.filter((l) => !downloads.results[l] && !downloads.queue.includes(l) && !(downloads.active && downloads.active.line === l))
  const files = filesIn(settings.folder)
  const portrait = H > W * 1.1
  const wide = !portrait && W >= 700 * z
  // Stacked on a short screen (a 2.8", a watch, a round panel's middle), the
  // two lists would leave the addresses no room: under the address field they
  // scroll as one instead, each as long as it is. A narrow screen says
  // Download with its icon alone.
  const headH = context.roundBox ? 0 : px(50)
  const filesWant = Math.round(Math.min(H * 0.4, px(42) + Math.max(1, files.length) * px(66)))
  const compact = !wide && H - (context.roundBox ? 4 : px(36)) - headH - px(48) - px(36) - filesWant < px(114)
  const narrow = W < px(300)

  const Button = ({ label, onClick, kind, icon }) => (
    <div
      className={`shrink-0 h-[${px(46)}px] px-[${px(compact ? 12 : 16)}px] rounded-[${px(12)}px] flex items-center justify-center gap-[${px(6)}px] text-[${px(17)}px] font-bold ${kind === 'primary' ? t.primary : kind === 'remove' ? t.remove : t.button}`}
      onClick={onClick}
    >
      {icon ? <Icon d={icon} size={px(20)} /> : null}
      {label}
    </div>
  )

  // What a line of the queue shows under its name.
  const statusOf = (line, host) => {
    if (downloads.active && downloads.active.line === line) {
      const a = downloads.active
      const seconds = Math.max(1, (Date.now() - a.startedAt) / 1000)
      const perSecond = a.offset / seconds
      const again = a.lastError ? `. Trying again: ${a.lastError}` : ''
      // With the size known (FrameOS 2026.11.12+ hands over the headers): how
      // far along, and roughly how long is left at the speed so far.
      if (typeof a.total === 'number' && a.total > 0) {
        const share = Math.min(1, a.offset / a.total)
        const left = a.offset > 0 ? timeLeft((a.total - a.offset) / perSecond) : ''
        return {
          text: `${ofText(a.offset, a.total)}, ${Math.floor(share * 100)}%${left ? `, ${left}` : ''}${again}`,
          tone: a.lastError ? t.error : t.muted,
          active: true,
          share,
        }
      }
      const rate = a.offset > 0 ? `, ${sizeText(Math.round(perSecond))}/s` : ''
      return { text: `${sizeText(a.offset)} so far${rate}${again}`, tone: a.lastError ? t.error : t.muted, active: true, share: null }
    }
    if (downloads.queue.includes(line)) return { text: `Waiting, from ${host}`, tone: t.muted }
    const r = downloads.results[line]
    if (!r) return { text: `From ${host}`, tone: t.muted }
    if (r.s === 'done') return { text: `Saved as ${baseName(r.path)}, ${sizeText(r.bytes || 0)}${r.whole ? ', sent whole' : ''}`, tone: t.ok }
    if (r.s === 'skipped') return { text: `Skipped: ${baseName(r.path)} is there already`, tone: t.muted }
    if (r.s === 'stopped') return { text: 'Stopped', tone: t.muted }
    return { text: `Failed: ${r.error}`, tone: t.error }
  }

  const QueueRow = ({ line }) => {
    const parsed = parseLine(line)
    const host = parsed.url.replace(/^[a-z]+:\/\//i, '').split(/[/?#]/)[0] || parsed.url
    const status = statusOf(line, host)
    const r = downloads.results[line]
    return (
      <div className={`flex items-center gap-[${px(10)}px] rounded-[${px(14)}px] pl-[${px(14)}px] pr-[${px(8)}px] py-[${px(8)}px] ${t.card}`}>
        <div className="flex-1 min-w-0 flex flex-col gap-[2px]">
          <span className={`truncate text-[${px(compact ? 16 : 18)}px] font-semibold`}>{parsed.name || line}</span>
          {status.active && status.share !== null ? (
            <div className={`h-[${px(8)}px] my-[${px(3)}px] rounded-full ${t.track}`}>
              <div className={`h-full rounded-full ${t.fill} w-[${Math.max(2, Math.round(status.share * 1000) / 10)}%]`} />
            </div>
          ) : status.active ? (
            <div className={`flex gap-[${px(3)}px] h-[${px(8)}px] my-[${px(3)}px]`}>
              {/* The size is not known until the end: the lit blocks move on with each chunk. */}
              {Array.from({ length: 12 }, (_, i) => (
                <div className={`flex-1 rounded-full ${i <= (downloads.active.chunks || 0) % 12 ? t.fill : t.track}`} />
              ))}
            </div>
          ) : null}
          <span className={`text-[${px(14)}px] ${status.tone === t.error ? 'line-clamp-3' : 'line-clamp-2'} ${status.tone}`}>{status.text}</span>
        </div>
        {status.active ? (
          <Button label="Stop" onClick={stop} />
        ) : downloads.queue.includes(line) ? null : (
          <Button
            label={r && r.s !== 'done' && r.s !== 'skipped' ? 'Retry' : r ? 'Again' : 'Get'}
            kind={r ? '' : 'primary'}
            onClick={() => queueLines([line], !!r && (r.s === 'done' || r.s === 'skipped'))}
          />
        )}
        {status.active ? null : (
          <div className={`shrink-0 w-[${px(compact ? 32 : 40)}px] h-[${px(46)}px] flex items-center justify-center ${t.muted}`} onClick={() => removeLine(line)}>
            <Icon d={CLOSE} size={px(22)} />
          </div>
        )}
      </div>
    )
  }

  const FileRow = ({ file }) =>
    asking === file.path ? (
      <div className={`flex items-center gap-[${px(8)}px] rounded-[${px(14)}px] pl-[${px(14)}px] pr-[${px(6)}px] py-[${px(6)}px] ${t.card}`}>
        <span className={`flex-1 min-w-0 truncate text-[${px(16)}px]`}>{`Delete ${file.name}?`}</span>
        <Button label="Cancel" onClick={() => frameos.remember('asking', '')} />
        <Button
          label="Delete"
          kind="remove"
          onClick={() => {
            // A file still coming in is stopped first.
            const current = readDownloads(app)
            if (current.active && current.active.path === file.path) stop()
            frameos.deleteAsset(file.path)
            frameos.remember('asking', '')
          }}
        />
      </div>
    ) : (
      <div className={`flex items-center gap-[${px(10)}px] h-[${px(58)}px] rounded-[${px(14)}px] pl-[${px(12)}px] pr-[${px(4)}px] ${t.card}`}>
        <Icon d={FILE} size={px(24)} className={`shrink-0 ${t.icon}`} />
        <span className={`flex-1 min-w-0 truncate text-[${px(17)}px]`}>{file.name}</span>
        <span className={`shrink-0 text-[${px(14)}px] ${t.muted}`}>{file.size >= 0 ? sizeText(file.size) : ''}</span>
        <div className={`shrink-0 w-[${px(46)}px] h-[${px(46)}px] flex items-center justify-center ${t.muted}`} onClick={() => frameos.remember('asking', file.path)}>
          <Icon d={BIN} size={px(22)} />
        </div>
      </div>
    )

  const heading = (text, extra) => (
    <div className={`flex items-center gap-[${px(8)}px] h-[${px(30)}px]`}>
      <span className={`flex-1 min-w-0 truncate text-[${px(14)}px] font-bold uppercase ${t.heading}`}>{text}</span>
      {extra}
    </div>
  )

  // A list: in a box of its own that scrolls, or as long as it is where the
  // page scrolls.
  const listBox = (children) =>
    compact ? (
      <div className={`flex flex-col gap-[${px(8)}px]`}>{children}</div>
    ) : (
      <div className="flex-1 min-h-0 overflow-y-auto">
        <div className={`flex flex-col gap-[${px(8)}px]`}>{children}</div>
      </div>
    )
  const queueBox = (
    <div className={`${compact ? 'shrink-0' : 'flex-1 min-h-0'} min-w-0 flex flex-col gap-[${px(6)}px]`}>
      {heading(
        busy ? `Downloading, ${downloads.queue.length + (downloads.active ? 1 : 0)} to go` : `Addresses, ${lines.length}`,
        pending.length > 1 && !busy ? (
          <span className={`text-[${px(15)}px] font-bold underline`} onClick={() => queueLines(pending)}>
            {`Get all ${pending.length}`}
          </span>
        ) : null,
      )}
      {listBox(
        lines.length ? (
          lines.map((line) => <QueueRow line={line} />)
        ) : (
          <span className={`text-[${px(16)}px] ${t.muted}`}>
            {"Type an address above, or list them in the scene's settings, one a line. Add -> name.ext after one to pick its name."}
          </span>
        ),
      )}
    </div>
  )

  // Side by side, the two lists share the width; stacked, the files take what
  // they need up to two fifths of the height, and the addresses the rest.
  const filesBox = (
    <div className={`${wide ? 'flex-1' : compact ? 'shrink-0' : `shrink-0 h-[${filesWant}px]`} min-h-0 min-w-0 flex flex-col gap-[${px(6)}px]`}>
      {heading(`In ${settings.folder || 'the assets folder'}, ${files.length} ${files.length === 1 ? 'file' : 'files'}`)}
      {listBox(files.length ? files.map((file) => <FileRow file={file} />) : <span className={`text-[${px(16)}px] ${t.muted}`}>Nothing here yet.</span>)}
    </div>
  )

  return (
    <div className={`flex flex-col w-full h-full gap-[${px(12)}px] ${context.roundBox ? 'p-[2px]' : `p-[${px(18)}px]`} ${t.page}`}>
      {context.roundBox ? null : <div className={`flex items-center gap-[${px(10)}px]`}>
        <Icon d={DOWNLOAD} size={px(34)} className={`shrink-0 ${t.icon}`} />
        <div className="flex-1 min-w-0 flex flex-col">
          <span className={`text-[${px(narrow ? 20 : 26)}px] font-bold truncate`}>Download to assets</span>
          <span className={`text-[${px(14)}px] ${t.muted} truncate`}>
            {`Into ${settings.folder ? settings.folder + '/' : 'the assets folder'}, ${settings.chunk / 1024} KB at a time. ${
              settings.existing === 'skip' ? 'Files already there are skipped.' : settings.existing === 'overwrite' ? 'Files already there are replaced.' : 'A file already there is kept, the new one numbered.'
            }`}
          </span>
        </div>
      </div>}
      <div className={`flex items-center gap-[${px(10)}px]`}>
        <input
          className={`flex-1 min-w-0 h-[${px(48)}px] px-[${px(14)}px] rounded-[${px(12)}px] text-[${px(17)}px] ${t.field}`}
          value={draft}
          placeholder="https://example.com/photo.jpg"
          onChange={(e) => frameos.remember('draft', e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') addTyped()
          }}
        />
        <Button label={narrow ? '' : 'Download'} kind="primary" icon={DOWNLOAD} onClick={addTyped} />
      </div>
      {wide ? (
        <div className={`flex-1 min-h-0 flex gap-[${px(16)}px]`}>
          {queueBox}
          {filesBox}
        </div>
      ) : (
        <div className={`flex-1 min-h-0 flex flex-col gap-[${px(12)}px] ${compact ? 'overflow-y-auto' : ''}`}>
          {queueBox}
          {filesBox}
        </div>
      )}
    </div>
  )
}

