// Downloading a file into the assets folder a chunk at a time.
//
// A download asks for one range of bytes at a time (Range: bytes=a-b). Where
// frameos.httpRequest hands over the headers (FrameOS 2026.11.12+), the first
// answer's content-range says the file's size: the progress is a percentage
// and the download stops exactly there. Before that it has the status and the
// body alone, and knows it has the whole file when a range comes back shorter
// than asked (206), or the server says the range starts past the end (416).
// A server that ignores Range answers 200 with the whole file at once.
//
// The state of the downloads is one private json field (`downloads`):
// {
//   queue: [line, ...],                 lines waiting their turn
//   force: [line, ...],                 of those, the ones asked for again: replaced if there
//   active: { line, url, path, offset, total, retries, chunks, startedAt } | null,
//   results: { [line]: { s: 'done' | 'skipped' | 'failed' | 'stopped', path, bytes, error, whole, at } },
// }
// A line is the text of a line of the URLs field: `https://… -> name.ext`.

// A line's URL and the file name it asks for, or what is wrong with it.
export function parseLine(line) {
  const text = String(line || '').trim()
  const arrow = text.indexOf('->')
  const url = (arrow >= 0 ? text.slice(0, arrow) : text).trim()
  const asked = arrow >= 0 ? text.slice(arrow + 2).trim() : ''
  if (!/^https?:\/\/[^\s/]+/i.test(url)) return { url, name: '', error: 'Not a web address: it starts with http:// or https://' }
  if (asked && /[\/\\]/.test(asked)) return { url, name: '', error: 'The name after -> is a file name, not a folder' }
  const name = cleanName(asked || nameFromUrl(url))
  return { url, name, error: '' }
}

// The last part of the URL's path, decoded: what the file is called there.
export function nameFromUrl(url) {
  const path = url.replace(/^[a-z]+:\/\/[^/]+/i, '').split(/[?#]/)[0]
  const last = path.split('/').filter(Boolean).pop() || ''
  try {
    return decodeURIComponent(last)
  } catch (e) {
    return last
  }
}

// A file name the assets folder takes: letters, digits and a few signs, no
// folder in it, no dot at the start (a hidden file), at most 96 characters
// with the extension kept.
export function cleanName(name) {
  let clean = String(name || '')
    .replace(/[\/\\]/g, '_')
    .replace(/[^A-Za-z0-9 ._()+,=@-]/g, '_')
    .replace(/_+/g, '_')
    .replace(/\s+/g, ' ')
    .replace(/^[\s.]+/, '')
    .trim()
  if (!clean || clean === '_') clean = 'download'
  if (clean.length > 96) {
    const dot = clean.lastIndexOf('.')
    const ext = dot > 0 && clean.length - dot <= 8 ? clean.slice(dot) : ''
    clean = clean.slice(0, 96 - ext.length) + ext
  }
  return clean
}

// The folder setting as a path in the assets folder: no "..", no hidden
// folders, no slashes at the ends. Empty is the assets folder itself.
export function cleanFolder(folder) {
  return String(folder ?? '')
    .split(/[\/\\]/)
    .map((part) => part.trim().replace(/^\.+/, '').replace(/[^A-Za-z0-9 ._()+,=@-]/g, '_'))
    .filter((part) => part && part !== '_')
    .join('/')
}

export const joinPath = (folder, name) => (folder ? `${folder}/${name}` : name)

// "report (2).pdf" for the first name not taken.
export function freeName(folder, name) {
  if (!frameos.assetExists(joinPath(folder, name))) return name
  const dot = name.lastIndexOf('.')
  const stem = dot > 0 ? name.slice(0, dot) : name
  const ext = dot > 0 ? name.slice(dot) : ''
  for (let n = 2; n < 1000; n++) {
    const candidate = `${stem} (${n})${ext}`
    if (!frameos.assetExists(joinPath(folder, candidate))) return candidate
  }
  return `${stem} (${Date.now()})${ext}`
}

// Bytes in a base64 string.
export function base64Bytes(b64) {
  const s = String(b64 || '')
  if (!s.length) return 0
  const padding = s.endsWith('==') ? 2 : s.endsWith('=') ? 1 : 0
  return Math.floor((s.length * 3) / 4) - padding
}

export function sizeText(bytes) {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(bytes < 10240 ? 1 : 0)} KB`
  if (bytes < 1024 * 1024 * 1024) return `${(bytes / 1048576).toFixed(bytes < 10485760 ? 1 : 0)} MB`
  return `${(bytes / 1073741824).toFixed(1)} GB`
}

// "2.4 of 8 MB": both in the total's unit.
export function ofText(done, total) {
  const units = [
    [1073741824, 'GB'],
    [1048576, 'MB'],
    [1024, 'KB'],
  ]
  const [size, unit] = units.find(([u]) => total >= u) || [1, 'B']
  const num = (n) => {
    const v = n / size
    return size === 1 ? String(Math.round(v)) : v < 10 ? String(Number(v.toFixed(1))) : String(Math.round(v))
  }
  return `${num(done)} of ${num(total)} ${unit}`
}

// "about 2 min left", from seconds.
export function timeLeft(seconds) {
  if (!Number.isFinite(seconds) || seconds < 0) return ''
  if (seconds < 5) return 'almost done'
  if (seconds < 60) return `about ${Math.ceil(seconds / 5) * 5} s left`
  if (seconds < 3600) return `about ${Math.round(seconds / 60)} min left`
  const hours = Math.floor(seconds / 3600)
  return `about ${hours} h ${Math.round((seconds - hours * 3600) / 60)} min left`
}

const STATUS_WORDS = {
  400: 'bad request',
  401: 'a login is needed',
  403: 'not allowed',
  404: 'not found',
  410: 'gone',
  429: 'too many requests, try later',
  500: 'server error',
  502: 'bad gateway',
  503: 'unavailable, try later',
  504: 'gateway timeout',
}

// An error from the HTTP client, said plainly.
function plainError(error) {
  const text = String(error || 'no answer')
  const exceeded = /exceeded (\d+) bytes/.exec(text)
  if (exceeded) return `The server sent the whole file at once, and it is bigger than the ${sizeText(Number(exceeded[1]))} this frame takes in one answer`
  if (/Local network access is off/.test(text)) return text
  if (/timed? ?out|timeout/i.test(text)) return 'The server took too long to answer'
  return text.length > 160 ? text.slice(0, 157) + '...' : text
}

// The file's whole size as the answer says it, or null where it does not:
// "bytes 0-65535/8388608" in content-range on a 206 (or "bytes */8388608" on
// a 416), content-length on a 200. FrameOS 2026.11.12 hands httpRequest's
// headers over (lower-case names); before that `headers` is undefined, and a
// download finds its end by a chunk that comes back short.
export function totalOf(res) {
  const headers = res && res.headers
  if (!headers || typeof headers !== 'object') return null
  if (res.status === 206 || res.status === 416) {
    const m = /\/\s*(\d+)\s*$/.exec(String(headers['content-range'] || ''))
    return m ? Number(m[1]) : null
  }
  if (res.status === 200 && headers['content-length'] !== undefined && !headers['content-encoding']) {
    const n = Number(headers['content-length'])
    return Number.isFinite(n) && n >= 0 ? n : null
  }
  return null
}

// The most a frame with little memory takes as one whole answer: its body
// becomes a JS string (a third bigger in base64) beside the runtime's copy.
const WHOLE_ON_EMBEDDED = 1024 * 1024

// Whether the server sends parts of a file, and how big it is, asked without
// the body ever becoming a JS string: `find` keeps it in the runtime, and a
// needle that is never there gives back only the status (and the headers). A
// frame with little memory asks this before the first chunk, so a server that
// ignores Range cannot hand it a file too big for its JavaScript.
export function probeRanges(url) {
  const res = frameos.httpRequest(url, {
    headers: { Range: 'bytes=0-0' },
    find: '\u0001frameos-range-probe\u0002',
    findLimit: 1,
    findLength: 1,
    timeoutMs: 30000,
  })
  return res
}

// One step of a download: a chunk fetched and written. Returns the job as it
// is now, and when it is over, `result` (what the queue shows for the line).
// `limits` = { chunk, maxBytes, embedded }. `job.total` is the file's size
// once an answer said it (null until then, and always on older frames).
export function step(job, limits) {
  const fail = (error, keepFile) => {
    if (!keepFile && job.offset > 0) frameos.deleteAsset(job.path)
    return { job: null, result: { s: 'failed', path: job.path, bytes: 0, error, at: Date.now() } }
  }
  const NOT_IN_PARTS =
    'This server sends only whole files, and this frame downloads in parts to fit its memory. A Raspberry Pi frame can get it.'
  const TOO_BIG = `Bigger than the ${sizeText(limits.maxBytes)} set as the largest file in the scene's settings`
  const answered = (status) => `The server answered ${status}${STATUS_WORDS[status] ? ` (${STATUS_WORDS[status]})` : ''}`
  const retry = (error) => {
    // Too big for one answer is not worth asking again.
    if (/exceeded \d+ bytes/.test(String(error))) return fail(limits.embedded ? NOT_IN_PARTS : plainError(error), false)
    const retries = (job.retries || 0) + 1
    if (retries >= 3) return fail(plainError(error), false)
    return { job: { ...job, retries, lastError: plainError(error) }, result: null }
  }
  const done = (bytes, whole) => ({ job: null, result: { s: 'done', path: job.path, bytes, whole: !!whole, at: Date.now() } })
  const write = (b64) => (job.offset === 0 ? frameos.writeAsset(job.path, b64) : frameos.appendAsset(job.path, b64))
  const CANNOT_WRITE = 'The frame could not write the file: it needs permission to write the assets folder, and room on its disk'

  if (limits.embedded && !job.probed) {
    const probe = probeRanges(job.url)
    if (!probe || probe.error || !probe.status) return retry(probe && probe.error)
    const total = totalOf(probe)
    if (probe.status === 200) {
      // The whole file at once: only when its size is known and small
      // enough for this frame's memory.
      if (total === null) return fail(NOT_IN_PARTS, true)
      if (total > WHOLE_ON_EMBEDDED)
        return fail(
          `This server sends only whole files, and this one (${sizeText(total)}) is more than the ${WHOLE_ON_EMBEDDED / 1048576} MB this frame takes in one piece. A Raspberry Pi frame can get it.`,
          true,
        )
      if (total > limits.maxBytes) return fail(TOO_BIG, true)
      job = { ...job, probed: true, total }
    } else if (probe.status === 206 || probe.status === 416) {
      if (total !== null && total > limits.maxBytes) return fail(TOO_BIG, true)
      job = { ...job, probed: true, total: total ?? job.total ?? null }
    } else {
      return fail(answered(probe.status), true)
    }
  }

  // Nothing left to ask for: the size said so (an empty file, or a chunk
  // that ended exactly at the end).
  if (typeof job.total === 'number' && job.offset >= job.total) {
    if (job.offset === 0) frameos.writeAsset(job.path, '')
    return done(job.offset, false)
  }

  const last = typeof job.total === 'number' ? Math.min(job.offset + limits.chunk, job.total) - 1 : job.offset + limits.chunk - 1
  const res = frameos.httpRequest(job.url, {
    headers: { Range: `bytes=${job.offset}-${last}` },
    base64: true,
    timeoutMs: 30000,
  })
  if (!res || res.error || !res.status) return retry(res && res.error)

  if (res.status === 206) {
    const total = job.total ?? totalOf(res)
    if (total !== null && total > limits.maxBytes) return fail(TOO_BIG, false)
    const b64 = res.bodyBase64 || ''
    const bytes = base64Bytes(b64)
    if (job.offset + bytes > limits.maxBytes) return fail(TOO_BIG, false)
    if (bytes > 0) {
      if (!write(b64)) return fail(CANNOT_WRITE, false)
    } else if (job.offset === 0) {
      frameos.writeAsset(job.path, '')
    }
    const offset = job.offset + bytes
    // The end: where the size says, else a chunk shorter than asked.
    if (total !== null ? offset >= total || bytes === 0 : bytes < limits.chunk) return done(offset, false)
    return { job: { ...job, offset, total, retries: 0, chunks: (job.chunks || 0) + 1, lastError: '' }, result: null }
  }
  if (res.status === 200) {
    // The server ignored the range and sent the whole file.
    const b64 = res.bodyBase64 || ''
    const bytes = base64Bytes(b64)
    if (bytes > limits.maxBytes) return fail(TOO_BIG, false)
    if (!frameos.writeAsset(job.path, b64)) return fail(CANNOT_WRITE, false)
    return done(bytes, true)
  }
  if (res.status === 416) {
    // The range starts past the end: the last chunk was exactly a chunk long.
    if (job.offset === 0) frameos.writeAsset(job.path, '')
    return done(job.offset, false)
  }
  return fail(answered(res.status), false)
}
